return {
    ["line.amana_joins.1"] = { en = "Enough. You have me. The coin is yours whatever happens next -- I am not asking you to give that up.", ja = "" },  -- TODO
    ["line.amana_joins.10"] = { en = "Those. The corruption you are paid to purge. Every one of them was a child in that hall a season ago.", ja = "" },  -- TODO
    ["line.amana_joins.11"] = { en = "I have put down three of those this year and been thanked for it.", ja = "" },  -- TODO
    ["line.amana_joins.12"] = { en = "And it kills. Most often, it simply kills. The body goes out the back and into a pit with no marker on it, and the register writes the child down as ascended to the Light.", ja = "" },  -- TODO
    ["line.amana_joins.13"] = { en = "The roll of our glorious dead is a casualty list. Everyone reads it aloud on the feast day. Nobody has ever once counted it.", ja = "" },  -- TODO
    ["line.amana_joins.14"] = { en = "...Say that last part again.", ja = "" },  -- TODO
    ["line.amana_joins.15"] = { en = "The register writes them down as ascended.", ja = "" },  -- TODO
    ["line.amana_joins.16"] = { en = "My order carves a mark for each of its dead and teaches children the marks are days held. Same trick. Different stone.", ja = "" },  -- TODO
    ["line.amana_joins.17"] = { en = "I am sorry. Go on. I did not mean to make this mine.", ja = "" },  -- TODO
    ["line.amana_joins.18"] = { en = "How old are they when they take them?", ja = "" },  -- TODO
    ["line.amana_joins.19"] = { en = "Six. Seven. Young enough not to remember being asked, because they were not.", ja = "" },  -- TODO
    ["line.amana_joins.2"] = { en = "I am asking for the walk back. That is all. Hear it, and then take me in if you still mean to.", ja = "" },  -- TODO
    ["line.amana_joins.20"] = { en = "Mm. Then I know the shape of your house, priest, and I have never set foot in it.", ja = "" },  -- TODO
    ["line.amana_joins.21"] = { en = "I hid nine of them. I would have hidden ninety. That is the whole of my crime and I will not pretend to regret it in front of you.", ja = "" },  -- TODO
    ["line.amana_joins.22"] = { en = "Then why is a Confessor standing in a wood alone? Why has nobody in that building said a word?", ja = "" },  -- TODO
    ["line.amana_joins.23"] = { en = "Because almost nobody in that building knows. That is what I need you to understand, and it is the part that sounds like an excuse.", ja = "" },  -- TODO
    ["line.amana_joins.24"] = { en = "The faith is real. The people in it are good. I have knelt beside them my whole life. It is a small circle around the rite -- and they have kept it from the rest of us for a generation.", ja = "" },  -- TODO
    ["line.amana_joins.25"] = { en = "If the Saint herself were told, plainly, with proof she could not put aside -- it would end that afternoon. I believe that. I have to; it is the last thing I have that is not on fire.", ja = "" },  -- TODO
    ["line.amana_joins.26"] = { en = "That is a great deal of weight on one woman's ignorance.", ja = "" },  -- TODO
    ["line.amana_joins.27"] = { en = "Yes. It is.", ja = "" },  -- TODO
    ["line.amana_joins.28"] = { en = "A rite that kills most of the ones it is done to is not a rite. It is a yield. Somebody is running it as a yield.", ja = "" },  -- TODO
    ["line.amana_joins.29"] = { en = "...I have not let myself put it that way.", ja = "" },  -- TODO
    ["line.amana_joins.3"] = { en = "Say it.", ja = "" },  -- TODO
    ["line.amana_joins.30"] = { en = "Somebody keeps that register. Ledgers don't write themselves, and the hand that keeps one always knows what it's for.", ja = "" },  -- TODO
    ["line.amana_joins.31"] = { en = "So. I cannot walk back in. I am fallen, and the word is theirs to give, and they have given it.", ja = "" },  -- TODO
    ["line.amana_joins.32"] = { en = "But you are not the faith's hand. You were hired by it once and you did not finish the job, which makes you the only outfit in this country I can say any of this to.", ja = "" },  -- TODO
    ["line.amana_joins.33"] = { en = "Take me with you. I will not ask you for a wage, or a share, or a say in where we go. I have never been much good at wanting things for myself -- they were thorough about that.", ja = "" },  -- TODO
    ["line.amana_joins.34"] = { en = "I only want to be standing somewhere the truth can still be carried. Let me carry it.", ja = "" },  -- TODO
    ["line.amana_joins.35"] = { en = "You can want a wage too. We'll start there.", ja = "" },  -- TODO
    ["line.amana_joins.36"] = { en = "...I will think about it.", ja = "" },  -- TODO
    ["line.amana_joins.4"] = { en = "The children the faith takes in are sorted. Most are made anointed -- the holy warriors you have cheered in the street. A few of us are kept back as clergy, and never blooded.", ja = "" },  -- TODO
    ["line.amana_joins.5"] = { en = "Blooded. That is the word for it. There is a rite, and the rite puts something into a child, and what it puts in is not the Light.", ja = "" },  -- TODO
    ["line.amana_joins.6"] = { en = "It is demon's blood.", ja = "" },  -- TODO
    ["line.amana_joins.7"] = { en = "...You are certain.", ja = "" },  -- TODO
    ["line.amana_joins.8"] = { en = "I stood close enough to be certain. Three things happen at that altar.", ja = "" },  -- TODO
    ["line.amana_joins.9"] = { en = "It takes -- and you get a soldier who will die gladly and never know what is in him. It takes wrong -- and you get a thing that is hunted afterwards, and called a demon out of the wild.", ja = "" },  -- TODO
    ["line.arcanum_general_pride_confront.1"] = { en = "Let me see you. There -- I have the whole of you in a glance. Every working you carry, and I hold the answer to each. Cast it, and it comes back to you.", ja = "" },  -- TODO
    ["line.arcanum_general_pride_confront.2"] = { en = "And little Gyeom, still behind that book. I taught circles around you once, and you learned to cower rather than shine. There is nothing in you I have not already surpassed.", ja = "" },  -- TODO
    ["line.arcanum_general_pride_confront.3"] = { en = "No. There is nothing in me you can see.", ja = "" },  -- TODO
    ["line.arcanum_general_pride_confront.4"] = { en = "Then show me something new, if you have it. You do not. I finished learning an age ago -- that is what it is to be the greatest. Come and be answered.", ja = "" },  -- TODO
    ["line.arcanum_the_radical_confront.1"] = { en = "The one you want is a clerk who mislaid her nerve. She has been freeing our subjects and hiding our materials -- theft from the realm's own defense. No gift worth the name; you will barely feel her. Bring her in.", ja = "" },  -- TODO
    ["line.arcanum_the_radical_confront.2"] = { en = "He is right that I am no one to be afraid of. Do your best against me. It is the only thing I have ever asked of myself.", ja = "" },  -- TODO
    ["line.arcanum_the_radical_confront.3"] = { en = "You have been told what the Arcanum makes. You have not been shown what it costs the ones it makes it from. Not yet.", ja = "" },  -- TODO
    ["line.arcanum_the_radical_confront.4"] = { en = "I will not run, and I will not show you everything I have. Come and see how far 'no one to be afraid of' takes you.", ja = "" },  -- TODO
    ["line.arena_debut_event.1"] = { en = "The tunnel to the sand is that way. And a man in a very good coat has been watching you since the gate.", ja = "" },  -- TODO
    ["line.arena_debut_event.2"] = { en = "House colors, no house name -- a booking man, here to price the nobody before the crowd does. Choose...", ja = "" },  -- TODO
    ["line.arena_debut_event.3"] = { en = "Hear his offer.", ja = "" },  -- TODO
    ["line.arena_debut_event.4"] = { en = "Walk past him to the sand.", ja = "" },  -- TODO
    ["line.arena_debut_event.5"] = { en = "...forty in coin to open the card, win or lose, so long as the show is good. He's already written the ending. I take the money anyway.", ja = "" },  -- TODO
    ["line.arena_debut_event.6"] = { en = "No handler, no leash, no debt at the door. Whatever happens on that sand is ours alone -- and we walk to it steady.", ja = "" },  -- TODO
    ["line.arena_debut_event.7"] = { en = "They put their opener up against a team with nothing behind it -- and look at her: a mismatch in her favor and she's glad of it. Not hungry, not bored, just happy for the fight. No one's read her opening in years. Go be the first.", ja = "" },  -- TODO
    ["line.arena_debut_kit.1"] = { en = "Someone kitted up for this card and never made it to the sand. Their bag's still here, straps cut in a hurry.", ja = "" },  -- TODO
    ["line.arena_debut_kit.2"] = { en = "Cleansing draughts -- a couple of clearwater vials and a panacea besides. Choose...", ja = "" },  -- TODO
    ["line.arena_debut_kit.3"] = { en = "Take the lot.", ja = "" },  -- TODO
    ["line.arena_debut_kit.4"] = { en = "Rowan -- why would a fighter bring these to a sword bout?", ja = "" },  -- TODO
    ["line.arena_debut_kit.5"] = { en = "Because a house like the one we're drawn against doesn't win with the sword alone -- it fields netters. They'll rope your legs and hold you still while the big blade winds up. Drink one the moment you're pinned and it cuts you loose -- you get your step back before the swing lands. A panacea will do the same for whoever's caught beside you. Don't stand there roped, waiting for it.", ja = "" },  -- TODO
    ["line.arena_debut_kit.6"] = { en = "Cut loose, then move. Understood. Let's not keep the veteran waiting.", ja = "" },  -- TODO
    ["line.arena_saber_joins.1"] = { en = "Footsteps behind us -- the same weight that put me on my back an hour ago. She followed us out.", ja = "" },  -- TODO
    ["line.arena_saber_joins.2"] = { en = "Easy, knight. If I meant you harm I'd not announce it with my boots.", ja = "" },  -- TODO
    ["line.arena_saber_joins.3"] = { en = "Saber. That's the name the card gives me, and it'll do -- you'll have heard the house one shouted over the sand. Forget that one. It was rented.", ja = "" },  -- TODO
    ["line.arena_saber_joins.4"] = { en = "I open every bout the same way, and no one has read it in years. You two did -- and I had more fun losing that than I've had winning since I can remember. You didn't flinch at the crowd, you didn't flinch at me, and nobody paid you to stand there.", ja = "" },  -- TODO
    ["line.arena_saber_joins.5"] = { en = "{name}. No house, no handler, no leash at the gate. Someone will tell you that's a weakness before the week's out. It isn't. On that sand it is the only thing worth owning.", ja = "" },  -- TODO
    ["line.arena_saber_joins.6"] = { en = "There is a reckoning owed under this arena. Its patron has eaten better fighters than me, one at a time, because one at a time is how she likes them. I cannot reach her alone. You are the first outfit I've met that might.", ja = "" },  -- TODO
    ["line.arena_saber_joins.7"] = { en = "So. No coin this round, no booking, no ending written for me before the bell -- just the first fight in years I'd follow off the sand. I'm asking straight: take me on.", ja = "" },  -- TODO
    ["line.arena_saber_joins.8"] = { en = "You unseated a sworn knight in front of a house that wanted you to win, veteran. I would far rather have that swinging beside us than waiting on the next card.", ja = "" },  -- TODO
    ["line.arena_saber_joins.9"] = { en = "Then it's a team, and it has nothing behind it, and I have wanted that for longer than I'd say. Lead on. Let's see how far it goes.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.1"] = { en = "You've counted the marks on the gate, I expect. Everyone does.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.2"] = { en = "Forty-one. And every child in the order is taught that means forty-one days held.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.3"] = { en = "It doesn't. It means forty-one of us said yes.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.4"] = { en = "One mark each. She cut them herself, so nobody could ever say afterwards that they had been carried.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.5"] = { en = "...", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.6"] = { en = "We still say it, girl. Every dawn, in your forms, in your order of ranks.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_confront.7"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_intro.1"] = { en = "They are still a company. Still drilled, still in our forms, still answering a muster. Forty-one of them.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_intro.2"] = { en = "Forty-one.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_intro.3"] = { en = "They kept every part of the oath except the part that cost anything.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_intro.4"] = { en = "Then they will be between her and us, and they will be very good at it.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_outro.1"] = { en = "Forty-one people said it in the same breath and then walked out through the gate.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_outro.2"] = { en = "It is the same sentence, {name}. Word for word. There is nothing you can do to a sentence to stop that happening to it.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_outro.3"] = { en = "...", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_outro.4"] = { en = "No. There is one thing.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_outro.5"] = { en = "You can be somewhere the day it costs something.", ja = "" },  -- TODO
    ["line.bastion_forty_first_day_outro.6"] = { en = "Let's go. She is four miles up that road and she has been waiting fifteen years to be told she was right.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.1"] = { en = "Fifteen years of knights have held that line because they can say my name over their shields.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.10"] = { en = "I know what mine is worth.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.11"] = { en = "I chose it.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.2"] = { en = "Take it from them and the Watch empties tonight. Not in a year. Tonight.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.3"] = { en = "I have done more for that line as a lie than I ever did with a shield in my hands. Put your weapon down and think about it honestly, which is more than the order ever managed.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.4"] = { en = "...You're right.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.5"] = { en = "Yes.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.6"] = { en = "I have thought about it every mile of that road and I cannot answer you. Perhaps it does empty. Perhaps I am about to cost the line more than you ever did.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.7"] = { en = "But you never chose that post. It was issued to you. And when it came due you set it down, and you have spent fifteen years making that the truth about every post there has ever been, so that yours would stop being a thing you did.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.8"] = { en = "You. Girl. You have someone standing at your back.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_confront.9"] = { en = "Look at them properly. No post is worth holding -- and that includes theirs.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_intro.1"] = { en = "Past the gate that was opened from within.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_intro.2"] = { en = "Sworn -- the order does not require this of you.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_intro.3"] = { en = "No. It wouldn't.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_intro.4"] = { en = "{name}. Whatever she says to me in there, I have already said it to myself on every mile of the road here. Don't worry about me.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_intro.5"] = { en = "...Worry a little. But keep it to yourself.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.1"] = { en = "She was smaller than the shield made her.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.2"] = { en = "They will read her name at muster tomorrow. Nobody there will know, and I am not going to be the one who tells them -- not this month.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.3"] = { en = "Maybe the line empties. She may have been right about that. I will find out with everybody else.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.4"] = { en = "{name}.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.5"] = { en = "Fifteen years the order taught me to hold until relieved, and I never once noticed that it is a sentence about waiting for someone else to decide you may stop.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.6"] = { en = "I am not waiting to be relieved. I am not the relief either -- I tried that, it only meant running everywhere and arriving nowhere in particular.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.7"] = { en = "I am here, and it is you, and I picked it.", ja = "" },  -- TODO
    ["line.bastion_general_sloth_outro.8"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.bastion_greywatch_intro.1"] = { en = "Greywatch. Every knight in the order recites a doctrine named after that fort and I have never once stood in it.", ja = "" },  -- TODO
    ["line.bastion_greywatch_intro.2"] = { en = "There is nothing there, Sworn. It has stood empty fifteen years. The roof is in the courtyard.", ja = "" },  -- TODO
    ["line.bastion_greywatch_intro.3"] = { en = "Then it won't mind me walking it.", ja = "" },  -- TODO
    ["line.bastion_greywatch_intro.4"] = { en = "I want to see the ground she chose to die on. That is all. Humour me, {name}.", ja = "" },  -- TODO
    ["line.bastion_greywatch_outro.1"] = { en = "{name}. The bar. Look at the bar.", ja = "" },  -- TODO
    ["line.bastion_greywatch_outro.2"] = { en = "It's on the ground. On the INSIDE. You cannot lift a gate-bar from the wrong side of a gate -- that is the entire point of a bar.", ja = "" },  -- TODO
    ["line.bastion_greywatch_outro.3"] = { en = "Someone in this fort opened it.", ja = "" },  -- TODO
    ["line.bastion_greywatch_outro.4"] = { en = "She died holding a gateway that was already standing open behind her. Fifteen years and nobody in the order has said that out loud.", ja = "" },  -- TODO
    ["line.bastion_greywatch_outro.5"] = { en = "They let her name carry a doctrine and they never told a single one of us she was betrayed.", ja = "" },  -- TODO
    ["line.bastion_greywatch_outro.6"] = { en = "I want the file. Whatever the archive kept on Greywatch, I want it in my hands.", ja = "" },  -- TODO
    ["line.bastion_held_position_intro.1"] = { en = "A watchpost east of the river. There is nothing behind it worth defending -- the villages moved off that land twenty years ago.", ja = "" },  -- TODO
    ["line.bastion_held_position_intro.2"] = { en = "The garrison has been told, in writing, that they may stand down.", ja = "" },  -- TODO
    ["line.bastion_held_position_intro.3"] = { en = "And they haven't.", ja = "" },  -- TODO
    ["line.bastion_held_position_intro.4"] = { en = "They have not.", ja = "" },  -- TODO
    ["line.bastion_held_position_intro.5"] = { en = "Good.", ja = "" },  -- TODO
    ["line.bastion_held_position_intro.6"] = { en = "Come and stand with them, {name}. You have been taking my word for what the order is. Today you can watch it done properly.", ja = "" },  -- TODO
    ["line.bastion_held_position_outro.1"] = { en = "The sergeant asked me when the relief was due. I told him I didn't know.", ja = "" },  -- TODO
    ["line.bastion_held_position_outro.2"] = { en = "He said that was fine.", ja = "" },  -- TODO
    ["line.bastion_held_position_outro.3"] = { en = "He said it the way you'd say the weather was fine, {name}. Not bravely. It had just stopped being a question a long time ago.", ja = "" },  -- TODO
    ["line.bastion_held_position_outro.4"] = { en = "There is nothing behind that post. There has not been for twenty years. They know that better than the archive does -- they can see the empty fields from the wall.", ja = "" },  -- TODO
    ["line.bastion_held_position_outro.5"] = { en = "It is what we teach. It is what I would have done.", ja = "" },  -- TODO
    ["line.bastion_held_position_outro.6"] = { en = "I have never watched it from outside before, and I do not know what I watched.", ja = "" },  -- TODO
    ["line.bastion_muster_intro.1"] = { en = "Another name off the roll. There is always another.", ja = "" },  -- TODO
    ["line.bastion_muster_intro.2"] = { en = "How long is the roll?", ja = "" },  -- TODO
    ["line.bastion_muster_intro.3"] = { en = "Longer than last season.", ja = "" },  -- TODO
    ["line.bastion_muster_outro.1"] = { en = "Shorter line at the muster tent this time.", ja = "" },  -- TODO
    ["line.bastion_muster_outro.2"] = { en = "That's the third season running.", ja = "" },  -- TODO
    ["line.bastion_muster_outro.3"] = { en = "Don't say anything about it, {name}. I have already heard what I would say.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.1"] = { en = "Highwatch. Mountain post, top of the pass, warded on all four faces. It has been under siege for six weeks and without supply for twelve days.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.2"] = { en = "The column carrying its winter stores and its ward-salt is sitting at the bottom of that mountain and cannot get up it.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.3"] = { en = "Then they are still standing. Hold until relieved -- that is the order they were issued, and they will be keeping it.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.4"] = { en = "Twelve days, Sworn. On a rock, in winter.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.5"] = { en = "I have met men who held forty on a well that had gone dry.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.6"] = { en = "...That is the assumption the order makes, yes.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.7"] = { en = "The doctrine is hers. Acedia's. Everything I know about how to stand still and do nothing but wait, I learned off a woman who has been dead fifteen years.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.8"] = { en = "{name}. This isn't your line and it isn't your order. There is no shame in leaving it to people who swore to it.", ja = "" },  -- TODO
    ["line.bastion_relief_column_intro.9"] = { en = "But I gave you two words in the ash, and I meant both of them. So.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.1"] = { en = "Twelve days. We'd stopped counting somewhere around the eighth.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.2"] = { en = "And they opened the gate to you.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.3"] = { en = "Opened it? The sergeant came down the road on foot to meet the lead wagon. Wouldn't touch the flour. Went straight past me to the salt.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.4"] = { en = "Their wards were four days from going out. Four days, and then that mountain is just a wall with tired men on it.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.5"] = { en = "I gave the last of our water to the boy on the wagon on the ninth and told him a relief was coming. I didn't believe it when I said it.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.6"] = { en = "But they held.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.7"] = { en = "...Aye. They held.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.8"] = { en = "Forgive me, {name}. I'm no use at this part of it.", ja = "" },  -- TODO
    ["line.bastion_relief_column_outro.9"] = { en = "Somebody arrived. That's all I have ever wanted a story to say.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.1"] = { en = "You've the look. Bastion. Sworn, by the shield.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.2"] = { en = "Whose name do you carry, then?", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.3"] = { en = "Acedia's.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.4"] = { en = "Of course it is. They are still handing her out.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.5"] = { en = "Ask them where she is buried. Go on. Not what she did -- where she is buried.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.6"] = { en = "At Greywatch. Under the gate she died holding.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_confront.7"] = { en = "Is she.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_intro.1"] = { en = "The list. Knights who set their shields down. It is long, and we read it aloud.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_intro.2"] = { en = "Every Oathkeeper shield in the order carries a name off that list. We read them so they are not forgotten.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_intro.3"] = { en = "We read them so the entries can be closed.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_intro.4"] = { en = "One of them is still walking about in our forms, calling himself a captain.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_intro.5"] = { en = "...Then we close it.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_outro.1"] = { en = "He was forsworn. Forsworn men lie -- that is very nearly the definition of the word.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_outro.2"] = { en = "You don't get to set your shield down and then be believed about the woman who didn't.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_outro.3"] = { en = "...", ja = "" },  -- TODO
    ["line.bastion_the_long_list_outro.4"] = { en = "He wasn't lying about a fact, though, was he. He asked me a question.", ja = "" },  -- TODO
    ["line.bastion_the_long_list_outro.5"] = { en = "Say nothing, {name}. I'm arguing with a dead man and I'd rather do it alone.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_intro.1"] = { en = "The archive keeps everything. Including what it stopped reading.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_intro.2"] = { en = "Greywatch. The relief order that was cut for it. I want the date on the seal.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_intro.3"] = { en = "The archivist will not give you that.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_intro.4"] = { en = "I know. That's why I'm bringing {name} and not a requisition.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.1"] = { en = "Here. The relief order cut for Greywatch. Sealed, dated, countersigned by two hands.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.10"] = { en = "I would rather have been late.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.11"] = { en = "Late is a thing a person can carry. Late means there was a door and I did not reach it in time, and a woman was on the other side of it holding.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.12"] = { en = "Take that away and I am not someone who was late. I am someone who built herself, brick by brick, out of an apology to a person who never needed one.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.13"] = { en = "So no. I'll keep the guilt, thank you.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.14"] = { en = "And we are not finished. Somebody in this order cut that seal, and somebody has been reading her name aloud ever since.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.2"] = { en = "Issued on the nineteenth.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.3"] = { en = "The gate was opened on the fourteenth.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.4"] = { en = "Five days, {name}. She opened it five days before anyone in this order was so much as ORDERED to come for her.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.5"] = { en = "There was no relief. There was nothing to be late for.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.6"] = { en = "\"Rowan. There was never anything you could have done.\"", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.7"] = { en = "\"...\"", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.8"] = { en = "Don't. Don't you hand me that.", ja = "" },  -- TODO
    ["line.bastion_the_order_given_outro.9"] = { en = "Say it. You want to say it. That I'm innocent, that I was sixteen, that the mule was not the problem.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.1"] = { en = "Close enough. You've the walk. Which house?", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.10"] = { en = "They fed us. At the gate. Standing up.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.11"] = { en = "And then a man I had trained beside told me there was no place, and could not look at the wall behind my head while he said it.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.12"] = { en = "That is not how the order treats a knight who kept his oath.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.13"] = { en = "No.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.14"] = { en = "It isn't.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.15"] = { en = "...Then what did you do that they would not have you back?", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.16"] = { en = "I have spent fifteen years telling that to people who decided I was a liar before I opened my mouth. You've a sword out and the order's coin in your pocket. You'll forgive me if I don't spend the breath.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.17"] = { en = "Ask them. Ask them why we couldn't come home, and watch which way they look while they answer.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.18"] = { en = "Now. We've taken no lives on this road and we don't intend to start. But we're not being taken either, so make your peace and come on.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.2"] = { en = "The Bastion.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.3"] = { en = "...Of course. They still send them out one at a time.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.4"] = { en = "You keep a picket line. You've a camp laid out in quarters and a man on the high ground. Bandits do not do that.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.5"] = { en = "No. They don't.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.6"] = { en = "You were sworn.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.7"] = { en = "Sixty of us. On a gate. A long way east of anywhere your quartermaster has been.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.8"] = { en = "Then you deserted it.", ja = "" },  -- TODO
    ["line.bastion_turned_back_confront.9"] = { en = "Girl, I walked to the nearest chapter house of your order with what was left of my company behind me, and I stood in the yard for two days.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.1"] = { en = "A crew on the eastern road. Six wagons in a season, no lives taken, nothing burned.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.10"] = { en = "...As you say.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.11"] = { en = "{name} -- a word before we go.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.12"] = { en = "Every quarter I have served, the order has wanted men like that alive and talking. You bring in a deserter, you read him the list, he goes back on the line where he is some use.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.13"] = { en = "I have never once been told to end one.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.14"] = { en = "It will be in the reports somewhere and I will find it when we're back. Come on.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.2"] = { en = "That is not a crew, that is a garrison. Who are they?", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.3"] = { en = "Road-men.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.4"] = { en = "Road-men leave bodies.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.5"] = { en = "These are to be ended, Squire. Not brought in. Ended.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.6"] = { en = "\"You know who they are, don't you.\"", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.7"] = { en = "\"Six wagons. That's it?\"", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.8"] = { en = "I know what the contract says. So do you.", ja = "" },  -- TODO
    ["line.bastion_turned_back_intro.9"] = { en = "Six that were reported. Take the work or leave it on the board.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.1"] = { en = "He had a picket rotation. He had his camp laid out in quarters and a man on the high ground.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.10"] = { en = "That is why I am the way I am. In case you had wondered and were too polite to ask.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.11"] = { en = "Let's go back. I want to read that contract.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.2"] = { en = "I have buried knights who did it worse and been told to write commendations over them.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.3"] = { en = "{name}, I want you to hear me say it while it is still fresh enough to be honest: I do not know what we did tonight.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.4"] = { en = "The order said end them. So they are ended. That is the entire paperwork.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.5"] = { en = "...", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.6"] = { en = "I was sixteen the first time I went out on a rotation. Relief column, the eastern posts. My whole duty was the water -- four skins on a mule, and I checked them at every halt like they were relics.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.7"] = { en = "We were eleven miles out when the word came back down the line. The post was already gone. Turn around.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.8"] = { en = "So we turned around, and I carried four full skins all the way home.", ja = "" },  -- TODO
    ["line.bastion_turned_back_outro.9"] = { en = "Fifteen years, and I have never once set down a full waterskin without finding out first who needed it.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_intro.1"] = { en = "I want to ask the order a question.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_intro.2"] = { en = "Ask it.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_intro.3"] = { en = "Did you know.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_intro.4"] = { en = "...", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_intro.5"] = { en = "Take the quest, Sworn.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.1"] = { en = "We knew. The terms are under seal in the second vault and they have been since the year it happened.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.10"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.2"] = { en = "She negotiated. Her life and her company's lives, for the gate. There was no siege. There was no desperate hour. It was a transaction and she got her price.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.3"] = { en = "We weighed a hard truth against a useful saint, knight, and we took the one that keeps the posts manned.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.4"] = { en = "Every man on that line holds because he can say her name. What would you have had us do?", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.5"] = { en = "...", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.6"] = { en = "{name}. Walk with me. Not far.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.7"] = { en = "I swore to you in the ash and I never asked you whether you wanted it.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.8"] = { en = "I would have sworn it to anyone burning that night. Anyone at all. That is not devotion, that is a reflex with a nice sentence on it, and I have been calling it my honour for a year.", ja = "" },  -- TODO
    ["line.bastion_what_the_bastion_knows_outro.9"] = { en = "So. Again, and properly this time. Not to an order. Not to a name off a shield. To you -- because I have looked at you and chosen, and I could have chosen otherwise.", ja = "" },  -- TODO
    ["line.cathedral_fallen_confessor_confront.1"] = { en = "The one before you wore our cloth. A Confessor, no less -- she knows the charge.", ja = "" },  -- TODO
    ["line.cathedral_fallen_confessor_confront.2"] = { en = "She stole children promised to the Light and hid them from the rite. That is theft from the faith. Purge her, and be paid.", ja = "" },  -- TODO
    ["line.cathedral_fallen_confessor_confront.3"] = { en = "Children. The faith did not ask them, and it did not ask me. It has never once asked.", ja = "" },  -- TODO
    ["line.cathedral_fallen_confessor_confront.4"] = { en = "And now it sends a stranger to take me back. I understand. Take is the only verb they were ever taught.", ja = "" },  -- TODO
    ["line.cathedral_fallen_confessor_confront.5"] = { en = "You have been told what I am. You have not been told what they are -- what waits for those children past that rite. Not yet.", ja = "" },  -- TODO
    ["line.cathedral_fallen_confessor_confront.6"] = { en = "I will not step aside, and I will not strike first. Beat me, then -- and before you collect your coin, you will hear me out.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.1"] = { en = "The little witness -- come back in their colors, a blade at your back. You saw the pits and could not look away, and here you are anyway. I never once feared you would come.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.2"] = { en = "I can take the blade. I can take every soul in these colors. But not you. There was never any of me put in you to call.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.3"] = { en = "You were the one we kept clean. No blooding, no leash. I used to think that a waste. Today I find it a mercy I can still spend.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.4"] = { en = "So let me give, for once -- the one thing this house took from you and never gave back.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.5"] = { en = "I keep every name that was traded for the cloth. Yours among them: the child you were, before they wrote a virtue over her and worked her to the bone inside it. Kneel, and it is yours again.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.6"] = { en = "...", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.7"] = { en = "That name is not yours to give. Taking it back from your hand would only be one more theft.", ja = "" },  -- TODO
    ["line.cathedral_general_lust_confront.8"] = { en = "I know what I am called. I gave it to myself. And that, I am keeping.", ja = "" },  -- TODO
    ["line.clem_joins.1"] = { en = "You had me, and you didn't cash me in. Do you know how rare that is, down here? Nobody does a thing for nothing. That's the whole disease.", ja = "" },  -- TODO
    ["line.clem_joins.2"] = { en = "The guild's the Bank's knife, and the Bank owns the government it bought the laws from. The debt isn't the gold -- it's the way everyone's been taught to think. I can't kill an idea. But I can burn the paper, and walk the ruined out.", ja = "" },  -- TODO
    ["line.clem_joins.3"] = { en = "{name}. Every kill I take, I turn into everyone's tempo and keep none -- that's the only way I know to pay down what I did with the same hands. Let me spend it on your road. I'll cost you nothing.", ja = "" },  -- TODO
    ["line.clem_joins.4"] = { en = "You'll cost us nothing, and we'll owe you plenty. Walk with us.", ja = "" },  -- TODO
    ["line.clem_joins.5"] = { en = "...Owe me nothing. That's the point. But yes. Let's go.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.1"] = { en = "Opening bout! On the sand -- nobody, no house, no record.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.2"] = { en = "And against them, on hire from no one in particular: Saber.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.3"] = { en = "On hire from whoever paid, thank you. It's a living.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.4"] = { en = "Right. You've not done this before, so -- two things, free, because I'd rather it was a bout than a mess.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.5"] = { en = "One. The crowd is not on your side and it is not against you. It does not know you exist yet. Stop listening to it.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.6"] = { en = "Two.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.7"] = { en = "Everyone your size opens careful. Feels each other out, three or four exchanges, learns the range.", ja = "" },  -- TODO
    ["line.colosseum_debut_confront.8"] = { en = "I don't.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.1"] = { en = "You came down the stair together, and one of you is favouring a left foot. You have been fighting already.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.10"] = { en = "I do not remember you. I do not remember anyone. That is not unkindness, it is the specification.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.11"] = { en = "I will tell you what I am, since you came all this way and will not otherwise believe it of a person.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.12"] = { en = "I have no fear. No pain. Nothing holds to me -- they saw to all of it before I could walk, and they were thorough, and I was very good.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.13"] = { en = "I felt nothing about being very good.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.14"] = { en = "Then one year somebody assigned to me broke protocol and talked to me. Described the room. Described the crowd. Told me what colour things were, which meant nothing and I have never forgotten a word of it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.15"] = { en = "And I was angry when they were taken away. That was the first thing I ever felt. It arrived whole, and it was mine, and it has been the only proof I have ever had that there is anyone in here.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.16"] = { en = "Taken away where?", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.17"] = { en = "Reassigned. There is a form. I have never seen where the form goes.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.18"] = { en = "...Oh.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.19"] = { en = "So there's nobody to collect from. Not one name at the bottom of it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.2"] = { en = "Good. I was told this was scheduled for the ninth. They moved it and did not say so, which is usual.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.20"] = { en = "No. I have looked. That is why it does not close.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.21"] = { en = "How old were you when they began?", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.22"] = { en = "There was no beginning. There is no part of me from before it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.23"] = { en = "...I know a house that does this. I did not know there were two.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.24"] = { en = "And the stable never once said what it had made.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.25"] = { en = "It cannot. Saying what I am means saying what the programme is, and the programme is still running. There are children in the intake tonight.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.26"] = { en = "You have described a life with one feeling in it and called that proof of a person. It is not much of a proof.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.27"] = { en = "It is the only one I was issued.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.28"] = { en = "Nothing in a wood is built like you. Every animal out there can be frightened. That is what keeps it alive.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.29"] = { en = "Yes. I have been told I am superb.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.3"] = { en = "Scheduled.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.30"] = { en = "Veteran. They say you put your sword down once, on a full house, and would not finish what you were told to finish.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.31"] = { en = "They died anyway. Somebody else did it while I stood there.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.32"] = { en = "I have thought about that more than I have thought about anything.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.33"] = { en = "Not whether it was right. I have no instrument for that. Only that a feeling went into you and a whole arena had to stop and wait for it. Mine has never moved anything at all.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.34"] = { en = "...Ira. I came down here believing I could take you out of it. That there was somewhere else you could be put.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.35"] = { en = "I know what you are offering. I had it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.36"] = { en = "There was no one in it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.37"] = { en = "So. Come and hit me properly. Not fast -- fast is nothing, and I have had a great deal of nothing.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.38"] = { en = "Every blow you land wakes a little more of me up. You will find that inconvenient. It is the only hour of my life I am ever present for, and I intend to be present for all of it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.39"] = { en = "That is not a reason to keep going.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.4"] = { en = "Everything I have done was scheduled. This is a card like any other card. You are on it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.40"] = { en = "It is the only one there is. Begin.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.41"] = { en = "I do not kill people who cannot choose.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.42"] = { en = "...Guard yourselves. I am going to do it anyway, and I would rather nobody tells me later that it was mercy.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.5"] = { en = "You are standing too still. Everyone shifts. You have been taught not to and you kept it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.6"] = { en = "Ira.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.7"] = { en = "That is the name, yes. You came out of the house.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.8"] = { en = "I washed out of it.", ja = "" },  -- TODO
    ["line.colosseum_general_wrath_confront.9"] = { en = "I know. They keep the ones who wash out in the ledger for a while, in case it takes late. Then they stop.", ja = "" },  -- TODO
    ["line.conversation_wrath_intro.1"] = { en = "So. Fresh blood for the sand. The crowd does love a debut -- win or die.", ja = "ほう、砂場に新しい血か。観衆はデビュー戦が大好きだ――勝つか、死ぬかだ。" },
    ["line.conversation_wrath_intro.2"] = { en = "We came to fight, not to be entertainment.", ja = "戦いに来た。見世物になりに来たわけじゃない。" },
    ["line.conversation_wrath_intro.3"] = { en = "Here they are the same thing. Tell me -- why should the arena remember your name?", ja = "ここでは同じことさ。言ってみろ――なぜ闘技場がお前の名を覚えるべきなのか?" },
    ["line.conversation_wrath_intro.4"] = { en = "\"Because we fight for coin.\"", ja = "「金のために戦うからだ。」" },
    ["line.conversation_wrath_intro.5"] = { en = "\"Because we fight for honor.\"", ja = "「誇りのために戦うからだ。」" },
    ["line.conversation_wrath_intro.6"] = { en = "Honest, at least. The purse is yours if you live.", ja = "少なくとも正直だな。生き延びれば賞金はお前のものだ。" },
    ["line.conversation_wrath_intro.7"] = { en = "Honor. The crowd will cheer it and forget it by morning.", ja = "誇りか。観衆は歓声を上げ、朝には忘れるだろう。" },
    ["line.conversation_wrath_intro.8"] = { en = "Then let us be quick about it. The Light is watching, even here.", ja = "では手短に済ませよう。光はここでも見ておられる。" },
    ["line.conversation_wrath_intro.9"] = { en = "Watching, and unimpressed. Open the gate.", ja = "見ていて、しかも呆れているがな。門を開けろ。" },
    ["line.crucible_general_envy_confront.1"] = { en = "There you are. Let me look at you -- all of you. Ah. That one. The strongest thing you brought. I will wear it now, and it will kill for me, and you will have to strike your own best to reach me.", ja = "" },  -- TODO
    ["line.crucible_general_envy_confront.2"] = { en = "Ren. You spend yourself into others and call it a life. I spent everything to be able to wear any of you, and I am still no one inside. Tell me how it looks -- from in there. Tell me how you make it look like nothing.", ja = "" },  -- TODO
    ["line.crucible_general_envy_confront.3"] = { en = "I would tell you. I would give it to you for free, if there were anyone in you to take it. That is the cruelty of what was done -- not that you are hollow, but that you would have received it, and cannot.", ja = "" },  -- TODO
    ["line.crucible_general_envy_confront.4"] = { en = "So I will see you, at least. You are real enough to be ended. That is more than they ever gave you.", ja = "" },  -- TODO
    ["line.crucible_the_counterfeiter_confront.1"] = { en = "The one you want has been forging clean-slate writs and stealing our reagents -- our discards, she calls them. She gives our craft away for nothing. Theft from the college. Bring her in.", ja = "" },  -- TODO
    ["line.crucible_the_counterfeiter_confront.2"] = { en = "He calls them discards. Look at the one behind me -- eyes sewn shut, and still afraid. That is what 'a self is inventory' makes.", ja = "" },  -- TODO
    ["line.crucible_the_counterfeiter_confront.3"] = { en = "I will not let you take her back to the vats. Come and try, if you were sent to. I would rather you saw this than believed him.", ja = "" },  -- TODO
    ["line.discipline_unlocked_alchemist.1"] = { en = "The {discipline}'s Work is unlocked to you, {name}. The Crucible releases its guarded cut for that method -- the shelf has more to offer you.", ja = "" },  -- TODO
    ["line.discipline_unlocked_alchemist.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_alchemist.3"] = { en = "You made this yours honestly. That is rarer here than the gear is. Take it.", ja = "" },  -- TODO
    ["line.discipline_unlocked_arcanum.1"] = { en = "You have opened the {discipline}'s discipline, {name}. The Arcanum unseals what it holds for that study -- the shelf is longer for you now.", ja = "" },  -- TODO
    ["line.discipline_unlocked_arcanum.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_arcanum.3"] = { en = "There is always more to learn on that road. Good. Take only what you will practise.", ja = "" },  -- TODO
    ["line.discipline_unlocked_bastion.1"] = { en = "You have earned the {discipline} road, {name}. The quartermaster has moved its gear onto your rack -- kit the Watch keeps for the ones who prove they can carry it.", ja = "" },  -- TODO
    ["line.discipline_unlocked_bastion.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_bastion.3"] = { en = "I trained beside a few who took that road. It is a good one. Do not let the rack outgrow the arm.", ja = "" },  -- TODO
    ["line.discipline_unlocked_cathedral.1"] = { en = "The {discipline}'s calling is open to you, {name}. What the Cathedral kept back for that path is on the shelf -- take what serves.", ja = "" },  -- TODO
    ["line.discipline_unlocked_cathedral.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_cathedral.3"] = { en = "The Light gives what is earned, and you earned this. Carry it gently.", ja = "" },  -- TODO
    ["line.discipline_unlocked_colosseum.1"] = { en = "The {discipline}'s work is on your card now, {name}. The stable stocks for the fighters who reach it -- and you reached it. Spend, and spend well.", ja = "" },  -- TODO
    ["line.discipline_unlocked_colosseum.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_colosseum.3"] = { en = "Knew you had it in you. That gear's sharper than the house lets most touch -- go on, kit up.", ja = "" },  -- TODO
    ["line.discipline_unlocked_hunters_lodge.1"] = { en = "You walk the {discipline}'s trail now, {name}. The Lodge sets out gear for the ones who get this far -- it is yours to draw.", ja = "" },  -- TODO
    ["line.discipline_unlocked_hunters_lodge.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_hunters_lodge.3"] = { en = "That path knows when to stop. Take the kit. Remember the lesson with it.", ja = "" },  -- TODO
    ["line.discipline_unlocked_undercroft.1"] = { en = "The {discipline}'s trade is yours now, {name}. The firm keeps stock off the open book for a hand that reaches it -- and you reached it. Quietly, mind.", ja = "" },  -- TODO
    ["line.discipline_unlocked_undercroft.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.discipline_unlocked_undercroft.3"] = { en = "Took me years to get shown that rack. You did it faster. Don't get sloppy with it.", ja = "" },  -- TODO
    ["line.flight_champion.1"] = { en = "Stop here, {name}. That one at the head of them is no imp -- it has a name where they carry none, and it leads this whole raiding party. This is the thing that has been walking the road behind us.", ja = "" },  -- TODO
    ["line.flight_champion.2"] = { en = "It's between us and the capital.", ja = "" },  -- TODO
    ["line.flight_champion.3"] = { en = "It is. And it will not fall to the swarm-work that served against the rest -- it takes blows the grunts could not, and the imps beside it only want to keep us busy while it reaches you.", ja = "" },  -- TODO
    ["line.flight_champion.4"] = { en = "Then we cut it down and the imps stop mattering.", ja = "" },  -- TODO
    ["line.flight_champion.5"] = { en = "Just so. Put it down and the road opens. Stay off its reach, let it come onto our line, and we end this at the gate rather than inside it. Ready when you are.", ja = "" },  -- TODO
    ["line.flight_event_shrine.1"] = { en = "A wayside shrine, still standing where everything around it burned.", ja = "" },  -- TODO
    ["line.flight_event_shrine.2"] = { en = "Someone tended it to the last -- and cut a healer's rite into the stone. It feels wrong to walk straight past. Choose...", ja = "" },  -- TODO
    ["line.flight_event_shrine.3"] = { en = "Kneel and learn the rite by heart.", ja = "" },  -- TODO
    ["line.flight_event_shrine.4"] = { en = "Tend our wounds and press on.", ja = "" },  -- TODO
    ["line.flight_event_shrine.5"] = { en = "...there. It holds. I can set a wound to closing now, slow and sure -- even one that is not my own.", ja = "" },  -- TODO
    ["line.flight_event_shrine.6"] = { en = "Patched, and the worse for wear behind us. The rite we leave for whoever comes after -- we've a road to make.", ja = "" },  -- TODO
    ["line.flight_event_shrine.7"] = { en = "The capital, then. Keep moving.", ja = "" },  -- TODO
    ["line.flight_event_survivor.1"] = { en = "Hold. Someone's in the brush -- hurt, and trying not to be heard.", ja = "" },  -- TODO
    ["line.flight_event_survivor.2"] = { en = "Easy. We're not with the things that did this. Choose...", ja = "" },  -- TODO
    ["line.flight_event_survivor.3"] = { en = "Ask which way the demons went.", ja = "" },  -- TODO
    ["line.flight_event_survivor.4"] = { en = "Share what little we carry, and press on.", ja = "" },  -- TODO
    ["line.flight_event_survivor.5"] = { en = "...north, along the ridge, in numbers. Good -- we take the low road. And she gave you the tell: where a demon's guard runs thin, if you mark it before the strike.", ja = "" },  -- TODO
    ["line.flight_event_survivor.6"] = { en = "Nothing to spare but thanks -- and she gave that freely. A vial of solvent, pressed on you in kind: splash it and a demon cannot grip its blade.", ja = "" },  -- TODO
    ["line.flight_event_survivor.7"] = { en = "An apothecary, before the fires. Then the capital: reach the walls.", ja = "" },  -- TODO
    ["line.gate_below_confront.1"] = { en = "You came a long way down to meet me, and there is no me to meet.", ja = "" },  -- TODO
    ["line.gate_below_confront.10"] = { en = "I know. I stopped waiting. You are forty-one days too late to frighten me with it.", ja = "" },  -- TODO
    ["line.gate_below_confront.11"] = { en = "There is nothing in you I have not already surpassed.", ja = "" },  -- TODO
    ["line.gate_below_confront.12"] = { en = "You are reciting. She meant it -- that was what was wrong with her. You are just holding the sound.", ja = "" },  -- TODO
    ["line.gate_below_confront.13"] = { en = "Kneel, and I will give you back the name they took.", ja = "" },  -- TODO
    ["line.gate_below_confront.14"] = { en = "I have a name. I gave it to myself, and you were not there.", ja = "" },  -- TODO
    ["line.gate_below_confront.15"] = { en = "The board never closes. There will be more in the spring. There are always more in the spring.", ja = "" },  -- TODO
    ["line.gate_below_confront.16"] = { en = "Then we will be there in the spring.", ja = "" },  -- TODO
    ["line.gate_below_confront.17"] = { en = "Everything made can be unmade cheaper. Ask the girl who was poured.", ja = "" },  -- TODO
    ["line.gate_below_confront.18"] = { en = "I did ask her. That is the difference between us, and it is not a small one.", ja = "" },  -- TODO
    ["line.gate_below_confront.19"] = { en = "Everything is owed. Everything comes back to the house in the end.", ja = "" },  -- TODO
    ["line.gate_below_confront.2"] = { en = "Seven appetites. That was the whole of it. Seven wants, and seven people who agreed to carry one each, because a want cannot walk about on its own.", ja = "" },  -- TODO
    ["line.gate_below_confront.20"] = { en = "Not this. This one I am writing off.", ja = "" },  -- TODO
    ["line.gate_below_confront.21"] = { en = "You see? I still have all of them. And I can put one back on whenever I care to.", ja = "" },  -- TODO
    ["line.gate_below_confront.22"] = { en = "So do it properly, if you are going to. Not the appetite this time.", ja = "" },  -- TODO
    ["line.gate_below_confront.23"] = { en = "The thing that was hungry.", ja = "" },  -- TODO
    ["line.gate_below_confront.24"] = { en = "That is what we came down for.", ja = "" },  -- TODO
    ["line.gate_below_confront.3"] = { en = "You took them off me one at a time. Careful work. I felt every one go the way you feel a tooth go -- not pain. An absence, with an edge on it.", ja = "" },  -- TODO
    ["line.gate_below_confront.4"] = { en = "Then there is nothing left of you.", ja = "" },  -- TODO
    ["line.gate_below_confront.5"] = { en = "Nothing is not the same as harmless.", ja = "" },  -- TODO
    ["line.gate_below_confront.6"] = { en = "I kept nothing of their souls. Souls are not food, and I was never sentimental. What I keep is the SHAPE a person makes when they say yes.", ja = "" },  -- TODO
    ["line.gate_below_confront.7"] = { en = "Come and be measured, little card-filler. You were always going to lose to somebody the house had already paid.", ja = "" },  -- TODO
    ["line.gate_below_confront.8"] = { en = "That is her mouth and it is not her. She never once said a thing she had been paid to say -- that was the whole trouble with her.", ja = "" },  -- TODO
    ["line.gate_below_confront.9"] = { en = "Hold until relieved. Nobody is coming, girl. Nobody was ever coming.", ja = "" },  -- TODO
    ["line.gate_below_ending.1"] = { en = "...", ja = "" },  -- TODO
    ["line.gate_below_ending.10"] = { en = "There is a reckoning owed under this floor and it is paid. I have wanted that since before I had a name that was mine to give out.", ja = "" },  -- TODO
    ["line.gate_below_ending.11"] = { en = "Nobody booked this one. Nobody wrote the ending. It came out how it came out, and it is ours.", ja = "" },  -- TODO
    ["line.gate_below_ending.12"] = { en = "Listen to it. That is the quietest a wood has been in my whole life, and I have spent my whole life making woods quiet.", ja = "" },  -- TODO
    ["line.gate_below_ending.13"] = { en = "I do not think I have to any more.", ja = "" },  -- TODO
    ["line.gate_below_ending.14"] = { en = "You are all standing. I want to say that out loud, because I spent the entire way down assuming I would be counting.", ja = "" },  -- TODO
    ["line.gate_below_ending.15"] = { en = "Somebody put a hand under me on the stair, and I let them. That is new. I am keeping it.", ja = "" },  -- TODO
    ["line.gate_below_ending.16"] = { en = "Everything is owed, it said. Everything comes back to the house.", ja = "" },  -- TODO
    ["line.gate_below_ending.17"] = { en = "The house is a hole in the ground and I am walking out of it. Let it stay owed.", ja = "" },  -- TODO
    ["line.gate_below_ending.18"] = { en = "...including mine. Fine. Especially mine.", ja = "" },  -- TODO
    ["line.gate_below_ending.19"] = { en = "Nobody up there is going to know what this was.", ja = "" },  -- TODO
    ["line.gate_below_ending.2"] = { en = "It is not leaving anything behind.", ja = "" },  -- TODO
    ["line.gate_below_ending.20"] = { en = "The board will post work in the morning. The shops will open. Somebody will complain about the price of steel.", ja = "" },  -- TODO
    ["line.gate_below_ending.21"] = { en = "That is the whole of what we were for. That it stays boring up there.", ja = "" },  -- TODO
    ["line.gate_below_ending.22"] = { en = "Come on. It is a long stair and I would like to see the sky do the thing it does.", ja = "" },  -- TODO
    ["line.gate_below_ending.3"] = { en = "No shape on the floor. No last word. It emptied out like a coat coming off a hook.", ja = "" },  -- TODO
    ["line.gate_below_ending.4"] = { en = "Because that is what it was. We kept expecting a thing wearing seven appetites. It was seven appetites wearing a thing.", ja = "" },  -- TODO
    ["line.gate_below_ending.5"] = { en = "Take them off and you are not left with a monster. You are left with the hook.", ja = "" },  -- TODO
    ["line.gate_below_ending.6"] = { en = "Seven people said yes to it.", ja = "" },  -- TODO
    ["line.gate_below_ending.7"] = { en = "That part does not come off. We killed the wanting. We did not un-ask the question, and it was asked of them, and every one of them answered.", ja = "" },  -- TODO
    ["line.gate_below_ending.8"] = { en = "Forty-one of mine answered it too, and they were not monsters when they did. They were cold, and tired, and somebody offered.", ja = "" },  -- TODO
    ["line.gate_below_ending.9"] = { en = "I have stopped being able to tell that story as though the ending was obvious.", ja = "" },  -- TODO
    ["line.gyeom_joins.1"] = { en = "You have me. Or you have what I let you see -- I have found that is usually enough.", ja = "" },  -- TODO
    ["line.gyeom_joins.2"] = { en = "The Arcanum wins the wars the crown cannot, and everyone above it looks away from the wing where the winning is grown. I looked. The register calls them donors to knowledge. I have read what became of them.", ja = "" },  -- TODO
    ["line.gyeom_joins.3"] = { en = "{name}. You are the first outfit here that is not the Arcanum's hand. I do not need to be the greatest of anything. I only need to be a little more use tomorrow than I was today -- and I would rather spend that on your road than its shelves.", ja = "" },  -- TODO
    ["line.gyeom_joins.4"] = { en = "So take me on. I have a great deal left to learn, and I mean to.", ja = "" },  -- TODO
    ["line.gyeom_joins.5"] = { en = "Then keep whatever you keep. Walk with us.", ja = "" },  -- TODO
    ["line.hunters_lodge_general_gluttony_confront.1"] = { en = "Another hunter, come to the heart of my wood. Good. I am always hungry, little sister, and you smell like one of us.", ja = "" },  -- TODO
    ["line.hunters_lodge_general_gluttony_confront.2"] = { en = "Stay. Trade blows with me. Every one you land, I take back twofold -- and every one I land, I keep. Hunt me the long way, the way you were taught, and you will feed me until there is nothing of you left. There is no bottom to it. Take the crown, and you never have to stop.", ja = "" },  -- TODO
    ["line.hunters_lodge_general_gluttony_confront.3"] = { en = "I know exactly what you are offering. I have always known. It is the one thing I have spent my life refusing.", ja = "" },  -- TODO
    ["line.hunters_lodge_general_gluttony_confront.4"] = { en = "One shot. What the wood needs, and no more. Then I lay the bow down.", ja = "" },  -- TODO
    ["line.hunters_lodge_the_guide_confront.1"] = { en = "The bounty led us this deep. The trees closed behind us -- and they are starving, all of them. Nothing out here is afraid of us.", ja = "" },  -- TODO
    ["line.hunters_lodge_the_guide_confront.2"] = { en = "Because something upwind is eating the whole wood, and it has not left them enough. Stand your ground. The wolf and I will turn the mad ones back -- you only have to still be standing when they break.", ja = "" },  -- TODO
    ["line.hunters_lodge_the_guide_confront.3"] = { en = "Hold. When it is quiet, we will talk about what you are really hunting.", ja = "" },  -- TODO
    ["line.kaya_joins.1"] = { en = "You lived. Good. Most of the Lodge's people would not have -- they come out here to take, and the wood knows the difference.", ja = "" },  -- TODO
    ["line.kaya_joins.2"] = { en = "The thing hollowing this place out was a hunter once. The greatest they ever had. Hunt the sacred long enough and you become it -- that is the honor they were saving for me, though none of them would say so.", ja = "" },  -- TODO
    ["line.kaya_joins.3"] = { en = "{name}. I take only what I need, and it has kept me myself. But the wood I am part of is being devoured, and enough is the only thing that ever stops that kind of hunger. No outsider reaches the heart of it alone. I will lead you.", ja = "" },  -- TODO
    ["line.kaya_joins.4"] = { en = "Then lead. We'll take only what the wood can spare.", ja = "" },  -- TODO
    ["line.kaya_joins.5"] = { en = "See that you do. It is watching.", ja = "" },  -- TODO
    ["line.prologue_arrival.1"] = { en = "There it is. Walls still standing, gates still shut. The capital.", ja = "" },  -- TODO
    ["line.prologue_arrival.10"] = { en = "It's been like this for weeks. The demons push, a village burns, and everyone still breathing runs for the capital. The city's fit to burst, work's gone dry, and food with it.", ja = "" },  -- TODO
    ["line.prologue_arrival.11"] = { en = "But coin still moves for those who can hold a blade. Register with the Adventurers' Guild -- the quest board takes anyone who'll take a contract. Pays a good deal better than queuing for bread.", ja = "" },  -- TODO
    ["line.prologue_arrival.12"] = { en = "Work that pays. That, we can do.", ja = "" },  -- TODO
    ["line.prologue_arrival.13"] = { en = "The board, then. We'll want coin before we want anything else.", ja = "" },  -- TODO
    ["line.prologue_arrival.2"] = { en = "The Bastion holds this wall. If anywhere is still holding, {name}, it is behind these stones.", ja = "" },  -- TODO
    ["line.prologue_arrival.3"] = { en = "More of them. Third column through the gate since morning -- where are we meant to put them all?", ja = "" },  -- TODO
    ["line.prologue_arrival.4"] = { en = "Not under my roof, that's certain. Barely bread enough for the mouths already inside.", ja = "" },  -- TODO
    ["line.prologue_arrival.5"] = { en = "You there -- off the road, with the others. Nobody passes until they're processed. Names, and where you've run from.", ja = "" },  -- TODO
    ["line.prologue_arrival.6"] = { en = "Papers, a token, a seal, anything to say who you are. No? Then you'll wait like the rest of them until I say oth--", ja = "" },  -- TODO
    ["line.prologue_arrival.7"] = { en = "...That plate. That's Bastion steel. You're a sworn knight of the Order?", ja = "" },  -- TODO
    ["line.prologue_arrival.8"] = { en = "I held the eastern wall. The wall is ash now. I brought out who I could.", ja = "" },  -- TODO
    ["line.prologue_arrival.9"] = { en = "Forgive me, ser. We don't see many of the Order come through on foot these days. Pass -- you, and the ones at your back.", ja = "" },  -- TODO
    ["line.prologue_flee.1"] = { en = "It's gone. All of it. My oath was to this ground, and the ground is ash.", ja = "" },  -- TODO
    ["line.prologue_flee.2"] = { en = "So I swear a new one, and not to ground this time. To you.", ja = "" },  -- TODO
    ["line.prologue_flee.3"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.prologue_flee.4"] = { en = "To the capital, then. Its walls still stand... for now.", ja = "" },  -- TODO
    ["line.prologue_flier.1"] = { en = "Bounties, escorts, standing contracts... half of these want a company three times our size.", ja = "" },  -- TODO
    ["line.prologue_flier.2"] = { en = "This one doesn't.", ja = "" },  -- TODO
    ["line.prologue_flier.3"] = { en = "The Colosseum. They pay for a debut bout -- a single fight, on the sand, in front of a crowd. Win or lose, the purse is posted the same.", ja = "" },  -- TODO
    ["line.prologue_flier.4"] = { en = "A blood sport.", ja = "" },  -- TODO
    ["line.prologue_flier.5"] = { en = "A paying one, and it asks only two on the field. It is not the war we came to fight, {name}... but it is the coin we can earn today. Take it, and we eat.", ja = "" },  -- TODO
    ["line.prologue_intro.1"] = { en = "Fire on the eastern fields -- demons, real ones, not a soldier's tale! Run, child, run!", ja = "" },  -- TODO
    ["line.prologue_intro.2"] = { en = "{name}. Behind me, and stay there. This is the part of the oath I have been waiting to keep.", ja = "" },  -- TODO
    ["line.prologue_intro.3"] = { en = "They serve the Demon Lord. If the capital falls after us, there is nowhere left to run to.", ja = "" },  -- TODO
    ["line.prologue_intro.4"] = { en = "Then we hold this lane. You have watched me drill this a hundred times, {name} -- now you do it. Move when I move, strike what I strike.", ja = "" },  -- TODO
    ["line.prologue_ruins.1"] = { en = "I can still see the smoke from here. That's not just our roofs, is it.", ja = "" },  -- TODO
    ["line.prologue_ruins.10"] = { en = "I am certain of the walls. I am less certain of the road -- the army that did this is walking it too, and it is not in a hurry. Stay close, {name}, and we will get there before they do.", ja = "" },  -- TODO
    ["line.prologue_ruins.2"] = { en = "No. Look past the fords -- every steading down the valley is burning, and the ones that aren't are already cold. They came through the whole of it in a night.", ja = "" },  -- TODO
    ["line.prologue_ruins.3"] = { en = "Then there are others. People who ran, like we ran.", ja = "" },  -- TODO
    ["line.prologue_ruins.4"] = { en = "Almost certainly. Scattered, hiding, no idea which way is safe.", ja = "" },  -- TODO
    ["line.prologue_ruins.5"] = { en = "We find them. I'm not walking past someone who's still out there.", ja = "" },  -- TODO
    ["line.prologue_ruins.6"] = { en = "Good. That is the right instinct, and I would have argued you into it if you hadn't got there first. We take who we find, and we keep moving while we do it.", ja = "" },  -- TODO
    ["line.prologue_ruins.7"] = { en = "Moving where? There's nothing left behind us.", ja = "" },  -- TODO
    ["line.prologue_ruins.8"] = { en = "The capital. Its walls are the last ones standing between here and the sea, and they hold a great deal more than a village gate.", ja = "" },  -- TODO
    ["line.prologue_ruins.9"] = { en = "You don't sound certain.", ja = "" },  -- TODO
    ["line.prologue_victory.1"] = { en = "Enough -- enough! It's been years since anyone put me on my back on this sand.", ja = "" },  -- TODO
    ["line.prologue_victory.2"] = { en = "I've watched this place feed fighters to its patron, one after another. I will not be fed. And you two -- no house behind you, and you still put me down.", ja = "" },  -- TODO
    ["line.prologue_victory.3"] = { en = "Well fought. The Adventurers' Guild is always short of people who live through their first bout.", ja = "" },  -- TODO
    ["line.prologue_victory.4"] = { en = "You want the Demon Lord? So does everyone who's lost a home. But it is only strong because of its seven -- its generals, its appetites. Unmake them one by one, and the crown is hollow. The board is open to you. Start climbing.", ja = "" },  -- TODO
    ["line.prologue_victory.5"] = { en = "Walk out slow. I'll catch you past the gate -- there's a thing I mean to ask, and not with a booking man breathing on it.", ja = "" },  -- TODO
    ["line.prologue_village.1"] = { en = "Look at it, {name}. The mill, the eastern row, the well we drew from this morning -- all of it, inside a night.", ja = "" },  -- TODO
    ["line.prologue_village.2"] = { en = "This is not a raid. The Demon Lord's army empties whole valleys like this and moves on before the ash is cold.", ja = "" },  -- TODO
    ["line.prologue_village.3"] = { en = "Two of them have seen us, and they will not come to you. Watch how I take mine.", ja = "" },  -- TODO
    ["line.ren_joins.1"] = { en = "You could have finished me and collected. You didn't. Good -- then you have already seen more than the college wants you to.", ja = "" },  -- TODO
    ["line.ren_joins.2"] = { en = "They chase the oldest dream: to make a person from base matter. They keep failing, and the failures are people all the same. I can undo a little of it -- restore a discard, shield a batch marked for the vats. It is why they want me quiet.", ja = "" },  -- TODO
    ["line.ren_joins.3"] = { en = "{name}. I do the Work the honest way -- I make the base noble by giving, and I keep nothing back. Let me give it to your road instead of their shelves. Take me on.", ja = "" },  -- TODO
    ["line.ren_joins.4"] = { en = "Then give, and let us give something back to you for once.", ja = "" },  -- TODO
    ["line.ren_joins.5"] = { en = "...That is not how it works. But walk on. There is much to mend.", ja = "" },  -- TODO
    ["line.tutorial_flight.1"] = { en = "Walk to the chest ahead -- use WASD, the arrow keys, or click a tile.", ja = "" },  -- TODO
    ["line.tutorial_flight.2"] = { en = "Open your loadout to see what you found.", ja = "" },  -- TODO
    ["line.tutorial_flight.3"] = { en = "{select} an item in your stash to equip it to a hero.", ja = "" },  -- TODO
    ["line.tutorial_village.1"] = { en = "Like that. Now yours, {name} -- close the ground and put it down.", ja = "" },  -- TODO
    ["line.tutorial_village.10"] = { en = "{select} on the lit tile to move there.", ja = "" },  -- TODO
    ["line.tutorial_village.11"] = { en = "{select} on Clear Out in your grid to ready it.", ja = "" },  -- TODO
    ["line.tutorial_village.12"] = { en = "{select} on your own tile to spin.", ja = "" },  -- TODO
    ["line.tutorial_village.13"] = { en = "{select} on Jolt to ready it. Its cost is purple: that is mana, not stamina.", ja = "" },  -- TODO
    ["line.tutorial_village.14"] = { en = "{select} on the grunt to jolt it.", ja = "" },  -- TODO
    ["line.tutorial_village.15"] = { en = "{select} on the grunt to strike it -- its card slid down the order, so you act before it does.", ja = "" },  -- TODO
    ["line.tutorial_village.2"] = { en = "More of them, and they will not come near enough for a blade. Use your techniques. Get in among those two, where both can reach you.", ja = "" },  -- TODO
    ["line.tutorial_village.3"] = { en = "Now take it in hand.", ja = "" },  -- TODO
    ["line.tutorial_village.4"] = { en = "Turn on your heel, {name}. Open them both at once.", ja = "" },  -- TODO
    ["line.tutorial_village.5"] = { en = "That one is bigger. Take this too -- I never had the knack for it, and you may. It draws on something you have far less of than breath, so you get one.", ja = "" },  -- TODO
    ["line.tutorial_village.6"] = { en = "Let it have the spark. It will not know which way it is facing.", ja = "" },  -- TODO
    ["line.tutorial_village.7"] = { en = "There -- it is reeling, and you are not. That is what the spark bought you: a turn it does not get. Finish it, {name}.", ja = "" },  -- TODO
    ["line.tutorial_village.8"] = { en = "Not that, {name}. Do as I showed you.", ja = "" },  -- TODO
    ["line.tutorial_village.9"] = { en = "{select} on the imp to move in range and attack with your weapon.", ja = "" },  -- TODO
    ["line.undercroft_clem_confront.1"] = { en = "That one there is ours -- was ours. Best hand we ever ran, and now she burns our writs and walks our debtors out the back. Theft, plain theft. Collect her.", ja = "" },  -- TODO
    ["line.undercroft_clem_confront.2"] = { en = "Collect me. Listen to the word he uses. Everyone on this floor is a note to him -- including you, the second you can't pay.", ja = "" },  -- TODO
    ["line.undercroft_clem_confront.3"] = { en = "I cut throats for that ledger for years. Now I burn it. If you were sent to bring me in, come on -- but you'll have seen what I am first.", ja = "" },  -- TODO
    ["line.undercroft_general_greed_confront.1"] = { en = "My best blade, come home at last. I hold every note in this city, Clem. The almshouse, the crown's war -- and yours. You never could forgive your own debt. I can. Kneel, and I mark it paid.", ja = "" },  -- TODO
    ["line.undercroft_general_greed_confront.2"] = { en = "Take my gold and you take everything I lift off them -- gild your friends, empty their hands, and you will never want again. It is the one thing I have that no one can call in. Be owed, instead of owing. Be free.", ja = "" },  -- TODO
    ["line.undercroft_general_greed_confront.3"] = { en = "You'd absolve me, so I'd owe you the absolution forever. I know that trick. I taught it.", ja = "" },  -- TODO
    ["line.undercroft_general_greed_confront.4"] = { en = "I don't need your hand to clear it. I'll forgive myself, for free -- and burn every note in your vault on the way out. The city's paid. Keep the crown that starves you.", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.1"] = { en = "The Crucible. We refine your gear and brew your medicine, and we teach the one truth the others are too timid for: excellence is a substance, not a self. No one is born better. Anything can be transferred.", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.2"] = { en = "Transferred from whom?", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.3"] = { en = "From a source. Does a formula have feelings? A self is inventory, friend -- and we are the only ones honest enough to say so. Buy, and be improved.", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.4"] = { en = "A self is not inventory. I have held the ones you decanted and dropped. There was someone in each of them.", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.5"] = { en = "Ren. You could have been a Philosopher. Instead you give the Work away and weep over spoiled batches.", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.6"] = { en = "They were not batches. Sell {name} the tinctures. Keep the philosophy.", ja = "" },  -- TODO
    ["line.vendor_alchemist_intro.7"] = { en = "As you wish. The shelf is open. Improvement is only ever a purchase away.", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.1"] = { en = "The Arcanum. We win the wars the crown cannot and turn back the plagues its physicians can't name. Buy what you like -- everything on this shelf was earned by someone.", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.2"] = { en = "Earned by whom?", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.3"] = { en = "Does it matter, so long as it works? No one else can do what we do. That is the beginning and end of the question.", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.4"] = { en = "It matters. It always mattered.", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.5"] = { en = "Sister. You were the finest hand on this floor before you grew a conscience over it.", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.6"] = { en = "I grew eyes. Sell {name} the wares, and keep the rest.", ja = "" },  -- TODO
    ["line.vendor_arcanum_intro.7"] = { en = "...As you wish. The shelf is open. We only ask that what we sell be used as we intended -- and we always know when it is not.", ja = "" },  -- TODO
    ["line.vendor_bastion_intro.1"] = { en = "The Watch outfits those who hold -- shields that outlast the arm behind them, mail a knight can be found standing in. We do not arm those who run. State your post, or your reason for having none.", ja = "" },  -- TODO
    ["line.vendor_bastion_intro.2"] = { en = "I hold what's mine. That's post enough.", ja = "" },  -- TODO
    ["line.vendor_bastion_intro.3"] = { en = "I held a post on this order's line before I ever held a sword for {name}. Greywatch. The quartermaster knows the face, if not the years on it.", ja = "" },  -- TODO
    ["line.vendor_bastion_intro.4"] = { en = "Squire Rowan. Greywatch's own. It is an honor to arm you again.", ja = "" },  -- TODO
    ["line.vendor_bastion_intro.5"] = { en = "It is Rowan of no post now. I kept the oath and gave up the wall -- and I hold something better than a line these days. Outfit us both.", ja = "" },  -- TODO
    ["line.vendor_bastion_intro.6"] = { en = "Hold until relieved, then. The shelf is yours -- and the order remembers the ones who stay.", ja = "" },  -- TODO
    ["line.vendor_cathedral_intro.1"] = { en = "You come armed and you come clean. The faithful arm those who purge -- wards, relics, water that burns what should not walk. Kneel when you take them, and the taking is made holy.", ja = "" },  -- TODO
    ["line.vendor_cathedral_intro.2"] = { en = "I'll take them standing.", ja = "" },  -- TODO
    ["line.vendor_cathedral_intro.3"] = { en = "Give what is offered and no more, quartermaster. {name} came for a censer, not a catechism.", ja = "" },  -- TODO
    ["line.vendor_cathedral_intro.4"] = { en = "Sister. The cloth suits you still, whatever you tell the road.", ja = "" },  -- TODO
    ["line.vendor_cathedral_intro.5"] = { en = "It was never offered to me either -- it was put on me. I wear what I choose to now. Arm us, and keep the sermon.", ja = "" },  -- TODO
    ["line.vendor_cathedral_intro.6"] = { en = "...As you will. The shelf is open. The faith asks only that its gifts be used as it intended them -- and it always knows when they are not.", ja = "" },  -- TODO
    ["line.vendor_colosseum_intro.1"] = { en = "You walked off the sand still breathing, so the shelf is yours -- steel, leathers, the little cruelties that keep a fighter on the card one more week. No house behind you? Good. A house takes a cut. I only take coin.", ja = "" },  -- TODO
    ["line.vendor_colosseum_intro.2"] = { en = "Then coin is all you'll get.", ja = "" },  -- TODO
    ["line.vendor_colosseum_intro.3"] = { en = "He says that to every fresh name, {name}. The cut comes later, dressed as a favour -- I've worn three houses' colors and paid each one twice.", ja = "" },  -- TODO
    ["line.vendor_colosseum_intro.4"] = { en = "And yet here you stand, veteran, shilling for a team with nothing behind it.", ja = "" },  -- TODO
    ["line.vendor_colosseum_intro.5"] = { en = "Nothing behind it is the only thing on this sand I have ever trusted. Sell them the good leathers, not the ones you move on the losers.", ja = "" },  -- TODO
    ["line.vendor_colosseum_intro.6"] = { en = "...The good leathers, then. Win loud, {name}. The crowd keeps a name, and a name is the only thing here I can't sell you -- you earn that one blow by blow.", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.1"] = { en = "The Lodge. We clear the beasts that would eat your children and feed your town on what's left -- honest work, honest coin. The board's always open. Take a bounty, take a trophy.", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.2"] = { en = "Always open. It never closes?", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.3"] = { en = "The wild always makes more game. That is the mercy of it -- there is always another beast worth killing. Rank up, and one day you'll be a Grand Hunter, and they'll carve your name on the wall.", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.4"] = { en = "I have read the names on that wall. Some of them I hunted.", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.5"] = { en = "...You take only what you need, girl. That is why we could never crown you. You were the finest tracker the wood ever grew.", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.6"] = { en = "It is why the wood never turned on me. Sell {name} the bows. Keep the crown.", ja = "" },  -- TODO
    ["line.vendor_hunters_lodge_intro.7"] = { en = "As you like. The board's open. There's always another beast worth killing.", ja = "" },  -- TODO
    ["line.vendor_market_intro.1"] = { en = "Torches, boots, bread, and a potion or two the temples pretend they don't stock. Everything the road needs, {name}, and nothing it'll shrive you for wanting.", ja = "" },  -- TODO
    ["line.vendor_market_intro.2"] = { en = "And the price?", ja = "" },  -- TODO
    ["line.vendor_market_intro.3"] = { en = "Fair. That's the whole of the pitch. The seven houses up the hill sell you a name to become; I sell you what gets you to tomorrow to spend it. Come back whenever the road's been unkind.", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.1"] = { en = "No sign, no door you'd notice. Good -- you found us anyway. The Undercroft looks after its own, friend. Debts, and the quiet murder of the people who won't pay them. Everything on this floor belonged to someone else once. That's just business.", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.2"] = { en = "And the people it belonged to?", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.3"] = { en = "Owed. Everyone's owed, up above -- your house, your city's water, your king's war. We just hold the note. A debt is a debt. That's not cruelty, that's the world.", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.4"] = { en = "I used to say that word for word. I collected on it, too. That's the lie -- 'we look after our own,' over a floor that owns every soul on it.", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.5"] = { en = "Clem. You were the best blade we ever ran. Then you started burning the paper.", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.6"] = { en = "I started reading it. Sell {name} the kit. Keep the family.", ja = "" },  -- TODO
    ["line.vendor_undercroft_intro.7"] = { en = "As you like. Floor's open. Everything's for sale -- and everything's owed.", ja = "" },  -- TODO
